#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Vessel: first deploy to a plain VPS with deploy/compose.yaml.
# Runs on your own computer; every server step goes over SSH.
# Settings (including generated secrets) are kept at $ENV_FILE so a re-run
# picks up where you left off. Keep that file private.
ENV_FILE="${ENV_FILE:-$HOME/.vessel/deploy.env}"
mkdir -p "$(dirname "$ENV_FILE")" && chmod 700 "$(dirname "$ENV_FILE")"
REPO_URL="https://github.com/megistusXYZ/Remote-Record-Studio.git"
APP_DIR="/opt/vessel"

TOTAL_STAGES=9

remote() { ssh -o StrictHostKeyChecking=accept-new -o ConnectTimeout=10 "root@${SERVER_IP}" "$@"; }

banner "Deploy Vessel to your own server"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Rent a server (VPS)"
say "Vessel needs one Linux server: 2 vCPUs, 4 GB RAM, 40 GB disk, Ubuntu 24.04."
say "Pick one provider:"
step "Hetzner: best value, lots of included traffic (prices change; check yours)."
step "DigitalOcean: friendlier dashboard, a little more expensive."
note "Recording uploads and downloads use bandwidth; both include terabytes a month."
if [[ ! -f "$HOME/.ssh/id_ed25519.pub" ]]; then
  warn "You don't have an SSH key yet; the server login needs one."
  if confirm "Create one now (ssh-keygen, stored in ~/.ssh)?"; then
    ssh-keygen -t ed25519 -f "$HOME/.ssh/id_ed25519" -C "vessel-deploy"
  fi
fi
if [[ -f "$HOME/.ssh/id_ed25519.pub" ]]; then
  say "Your public SSH key (safe to share; paste it when the provider asks):"
  printf '\n%s\n\n' "$(cat "$HOME/.ssh/id_ed25519.pub")"
fi
ask PROVIDER "Type hetzner or digitalocean:"
if [[ "$(printf %s "$PROVIDER" | tr "[:upper:]" "[:lower:]")" == d* ]]; then
  open_url "https://cloud.digitalocean.com/droplets/new"
  step "Region: closest to you. Image: Ubuntu 24.04 (LTS) x64."
  step "Size: Basic, Regular, 2 vCPU / 4 GB."
  step "Authentication: SSH Key → New SSH Key → paste the key above."
  step "Create Droplet, then copy its public IPv4 address."
else
  open_url "https://console.hetzner.cloud/"
  step "Open (or create) a project → Add Server."
  step "Location: closest to you. Image: Ubuntu 24.04."
  step "Type: shared vCPU with 2 vCPU / 4 GB RAM (e.g. CX23 if offered)."
  step "SSH keys: Add SSH key → paste the key above. Keep the public IPv4 address."
  step "Create & Buy now, then copy the server's IPv4 address."
fi
ask SERVER_IP "Paste the server's IPv4 address:"
write_env PROVIDER "$PROVIDER"
write_env SERVER_IP "$SERVER_IP"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Domain and contact"
say "Vessel lives at a hostname you own, e.g. vessel.fm or studio.yourname.com."
ask VESSEL_DOMAIN "Site hostname (no https://):"
ask ACME_EMAIL "Email for certificate expiry notices:"
ask VESSEL_CONTACT "Footer 'Contact' email (Enter to use the GitHub issues page):"
write_env VESSEL_DOMAIN "$VESSEL_DOMAIN"
write_env ACME_EMAIL "$ACME_EMAIL"
[[ -n "$VESSEL_CONTACT" ]] && write_env VESSEL_CONTACT "$VESSEL_CONTACT"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Point DNS at the server"
say "At your domain's DNS (Cloudflare, Namecheap, ...), add four A records,"
say "each pointing to ${SERVER_IP}:"
step "${VESSEL_DOMAIN}"
step "relay.${VESSEL_DOMAIN}"
step "files.${VESSEL_DOMAIN}"
step "turn.${VESSEL_DOMAIN}"
warn "On Cloudflare, set all four to 'DNS only' (grey cloud) for this first launch."
note "The CDN can come later (OPERATIONS.md § 1); turn and files must stay DNS-only."
pause "Press Enter once the records are saved"
for host in "$VESSEL_DOMAIN" "relay.$VESSEL_DOMAIN" "files.$VESSEL_DOMAIN" "turn.$VESSEL_DOMAIN"; do
  printf '  waiting for %s → %s ' "$host" "$SERVER_IP"
  for _ in $(seq 1 60); do
    if [[ "$(dig +short A "$host" @1.1.1.1 | tail -n1)" == "$SERVER_IP" ]]; then printf '%s✓%s\n' "$GREEN" "$RESET"; break; fi
    printf '.'; sleep 10
  done
  [[ "$(dig +short A "$host" @1.1.1.1 | tail -n1)" == "$SERVER_IP" ]] || { printf '\n'; warn "$host doesn't point at $SERVER_IP yet; fix it and re-run."; exit 1; }
done

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Log in to the server"
say "Checking that this computer can reach the server over SSH as root..."
if remote 'echo connected: $(hostname), $(. /etc/os-release; echo $PRETTY_NAME)'; then
  printf '  %s✓ SSH works%s\n' "$GREEN" "$RESET"
else
  warn "SSH failed. Check the IP, and that the server was created with your SSH key."
  exit 1
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Prepare the server"
say "This installs Docker (official script from get.docker.com) and turns on the"
say "firewall, allowing only SSH, web (80/443) and the live-video relay ports."
if confirm "Prepare ${SERVER_IP} now?"; then
  remote 'bash -s' <<'REMOTE'
set -euo pipefail
export DEBIAN_FRONTEND=noninteractive
apt-get update -qq && apt-get install -y -qq git ufw curl >/dev/null
command -v docker >/dev/null || curl -fsSL https://get.docker.com | sh >/dev/null
ufw allow 22/tcp >/dev/null
ufw allow 80 >/dev/null
ufw allow 443 >/dev/null
ufw allow 3478 >/dev/null
ufw allow 49160:49200/udp >/dev/null
ufw --force enable >/dev/null
echo "docker $(docker --version | cut -d' ' -f3 | tr -d ,), compose $(docker compose version --short)"
ufw status | head -12
REMOTE
  printf '  %s✓ server ready%s\n' "$GREEN" "$RESET"
else
  warn "Skipped. The next stages need Docker and open ports on the server."
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Settings and secrets"
POSTGRES_PASSWORD="$(_existing POSTGRES_PASSWORD || true)"
TURN_SHARED_SECRET="$(_existing TURN_SHARED_SECRET || true)"
[[ -n "$POSTGRES_PASSWORD" ]] || POSTGRES_PASSWORD="$(openssl rand -hex 32)"
[[ -n "$TURN_SHARED_SECRET" ]] || TURN_SHARED_SECRET="$(openssl rand -hex 32)"
write_env POSTGRES_PASSWORD "$POSTGRES_PASSWORD"
write_env TURN_SHARED_SECRET "$TURN_SHARED_SECRET"
chmod 600 "$ENV_FILE"
SERVER_ENV="$(mktemp)"
{
  echo "VESSEL_DOMAIN=${VESSEL_DOMAIN}"
  echo "ACME_EMAIL=${ACME_EMAIL}"
  echo "POSTGRES_PASSWORD=${POSTGRES_PASSWORD}"
  echo "TURN_SHARED_SECRET=${TURN_SHARED_SECRET}"
  echo "TURN_URLS=turn:turn.${VESSEL_DOMAIN}:3478?transport=udp,turn:turn.${VESSEL_DOMAIN}:3478?transport=tcp"
  echo "TURN_TTL_SECONDS=43200"
  [[ -n "${VESSEL_CONTACT:-}" ]] && echo "VESSEL_CONTACT_URL=mailto:${VESSEL_CONTACT}"
  echo "VESSEL_CSP_ENFORCE=true"
  echo "LOG_LEVEL=info"
  echo "VESSEL_RATE_LIMIT_MODE=observe"
  echo "BACKUP_KEEP_DAYS=14"
  # Nothing sits in front of the server yet, so no proxy may set the visitor IP.
  echo "TRUSTED_PROXY_RANGES=192.0.2.1/32"
} > "$SERVER_ENV"
say "Secrets were generated on this computer; a copy is kept at $ENV_FILE."
note "Keep that file private. It is the only copy outside the server."
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Start Vessel"
say "Fetching the code on the server and starting every service."
note "The first start downloads images and builds the sync server: a few minutes."
remote "test -d ${APP_DIR}/.git && git -C ${APP_DIR} pull -q --ff-only || git clone -q ${REPO_URL} ${APP_DIR}"
scp -q -o StrictHostKeyChecking=accept-new "$SERVER_ENV" "root@${SERVER_IP}:${APP_DIR}/deploy/.env"
rm -f "$SERVER_ENV"
remote "chmod 600 ${APP_DIR}/deploy/.env && cd ${APP_DIR} && C='docker compose -f deploy/compose.yaml --env-file deploy/.env' && \$C pull -q && \$C up -d && \$C ps --format 'table {{.Service}}\t{{.Status}}'"
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Verify"
check() { if eval "$2" >/dev/null 2>&1; then printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; else printf '  %s✗%s %s\n' "$RED" "$RESET" "$1"; FAILED=1; fi; }
FAILED=0
printf '  waiting for the site and its certificate '
for _ in $(seq 1 30); do curl -fsS "https://${VESSEL_DOMAIN}/api/healthz" >/dev/null 2>&1 && break; printf '.'; sleep 10; done
printf '\n'
check "API healthy at https://${VESSEL_DOMAIN}/api/healthz" "curl -fsS https://${VESSEL_DOMAIN}/api/healthz | grep -q '\"status\":\"ok\"'"
check "Site serves the app" "curl -fsS https://${VESSEL_DOMAIN}/ | grep -q '<div id=\"root\">'"
check "Security policy enforced" "curl -fsSI https://${VESSEL_DOMAIN}/ | grep -qi '^content-security-policy:'"
check "Storage server answers at files.${VESSEL_DOMAIN}" "curl -fsSI https://files.${VESSEL_DOMAIN}/"
check "Sync server answers at relay.${VESSEL_DOMAIN}" "curl -fsS -H 'Accept: application/nostr+json' https://relay.${VESSEL_DOMAIN}/ | grep -q '\"software\"'"
if (( FAILED )); then
  warn "Something isn't up yet. Logs: ssh root@${SERVER_IP} 'cd ${APP_DIR} && docker compose -f deploy/compose.yaml --env-file deploy/.env logs --tail=50'"
fi
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "First live check and day two"
open_url "https://${VESSEL_DOMAIN}"
step "Create a studio, start a session, and join from a phone on mobile data."
step "If you see each other live, the TURN relay works; record a minute and stop."
say "Day two:"
step "Update: re-run this wizard, or on the server: git pull, then compose pull and up -d."
step "Backups: a database dump is written daily on the server; copy them off it (OPERATIONS.md § 12)."
step "Uptime: add a free monitor for https://${VESSEL_DOMAIN}/api/healthz (e.g. UptimeRobot)."
step "After a quiet first week, set VESSEL_RATE_LIMIT_MODE=enforce in ${APP_DIR}/deploy/.env and run up -d."
pause "Press Enter to finish"

finish
